HELP_TOPICS = {'mode_border_plate': {'title': 'Forma base: Moldura (Border) vs. Placa / Inlay (Plate)', 'short': 'Alterna entre uma moldura aberta (Border) e uma placa contínua de metal ou vidro (Plate).', 'detail': '• MOLDURA (Border): o centro fica aberto (transparente) para emoldurar sua foto ou arte.\n• PLACA / INLAY (Plate): o centro é preenchido como chapa metálica escovada, vidro semitransparente ou leito de inlay colorido (ideal para logotipos, selos e placas).'}, 'grow_direction': {'title': 'Direção de crescimento (Para fora, Para dentro, Ambos)', 'short': 'Controla se a moldura cresce para fora, para dentro ou centrada na borda da seleção.', 'detail': '• Para fora (Expandir imagem): a moldura é construída fora da seleção. Se faltar margem, o Borderlay amplia automaticamente a tela do GIMP.\n• Para dentro: a moldura cresce da borda da seleção para o centro.\n• Ambos (Centrado): a moldura fica sobre a borda (50 % para fora, 50 % para dentro).'}, 'corner_radii': {'title': 'Cantos e raios (Raio externo e interno)', 'short': 'Controla o arredondamento dos cantos externos e internos (0 px = meia-esquadria viva de 45°).', 'detail': '• Suave / Médio / Sutil (Raio > 0 px): cria cantos concêntricos arredondados como uma placa prensada.\n• Meia-esquadria 45° (0 / 0 px): cria uma moldura clássica com cantos de 90° e juntas diagonais reais de 45°.\n• Na aba «2. Geometria, raios e 3D» é possível ajustar os raios separadamente em pixels.'}, 'shape_toolbox': {'title': 'Formas de seleção e alinhamento', 'short': 'Define uma forma como seleção e a alinha. Não renderiza moldura.', 'detail': '• Toque em uma categoria acima. Cada forma é um bloco com seu ID abaixo (ex.: leaf.heart), também selecionável sob a prévia grande.\n• Tamanho, ângulo e parâmetros desenham a forma na hora em cor sólida sobre a imagem.\n• Aplicar remove a cor e define a seleção. Fechar sem aplicar remove a cor e restaura a seleção anterior.\n• Look inclui formas básicas, uma onda e um sorriso.\n• Atelier e Team adicionam chamas, engrenagens, folhas, ornamento, motivos festivos, arcos, parâmetros de onda, piscadela e ângulo.\n• Uma seleção retangular define a caixa de posicionamento: a forma inicia centrada mantendo a proporção. Sem seleção, inicia no centro com cerca de 60 % do lado menor.\n• Alinhar encosta a forma nessa caixa; as setas movem em passos de pixels inclusive além dela. Move a forma, não uma camada.'}, 'shape_rotation': {'title': 'Girar forma da seleção (Ângulo e pivô de 9 pontos)', 'short': 'Gira apenas a geometria da moldura ao redor do pivô escolhido — a imagem fica intacta!', 'detail': '• Ângulo (-180° a +180°): gira a geometria da moldura ou placa.\n• Folha: ponta em cima, caule embaixo. O pivô «borda inferior centro» coloca o caule no centro da rosácea.\n• Eixo pivô: define o ponto de ancoragem (Centro, Canto sup.-esquerdo, etc.).\n• Importante: sua foto NÃO é girada e a iluminação global permanece consistente.'}, 'repeat_rotation': {'title': 'Rotação repetida (Ângulo 1 -> Ângulo 2, passo e esmaecimento)', 'short': 'Gera automaticamente uma série girada (leque / caleidoscópio) com transparência progressiva.', 'detail': '• Ângulo inicial 1 e final 2 (°): define o intervalo angular da repetição.\n• Passo de rotação (°): intervalo angular entre cópias.\n• Ciclos: repete o ciclo deslocando levemente cada passagem com esmaecimento contínuo.\n• ou até ângulo: 0 mantém apenas os ciclos; um ângulo maior continua o passo enquanto ciclos estiver em 1.\n• Passos de fade (%): reduz suavemente a opacidade da primeira cópia (100 %) até a última.'}, 'inlay_color': {'title': 'Cor de vidro e inlay (incl. conta-gotas e amostras)', 'short': 'Define a cor de «Vidro cristal colorido» e dos sulcos e placas inlay.', 'detail': 'Onde essa cor atua?\n1. Em «Vidro cristal colorido», tinge todo o corpo de vidro e a refração.\n2. Em «Cavidade inlay colorida» no modo Placa, colore o espelho interno.\n3. No Editor multizonas, colore zonas definidas como «Cor Inlay (inlay)».\n\nDica: clique na barra de cor para abrir o seletor com conta-gotas ou escolha uma das 8 gemas.'}, 'metal_gradient': {'title': 'Degradê metálico e largura de transição', 'short': 'Alterna entre a curva física de liga de 7 pontos e degradês nativos do GIMP.', 'detail': '• Curva interna de 7 pontos (Recomendado): calcula a reflexão física luz/sombra de cada metal.\n• Degradê GIMP: substitui a curva por um degradê do GIMP.\n• Ajuste a transição entre rampas e platôs via «Suavidade do chanfro (%)».'}, 'dual_profile_cut': {'title': 'Corte transversal interativo e largura de transição', 'short': 'Mostra ao vivo onde atuam cores de zona, sulcos, opacidade da placa e transições.', 'detail': '• O corte mostra a elevação da borda externa (esquerda) até a zona interna (direita).\n• À direita mostra ao vivo se o centro fica aberto ou com placa na opacidade escolhida (%).\n• As faixas amarelas marcam a largura de transição ativa («Suavidade do chanfro»).\n• Na aba 5, clique em Z1..Zn no gráfico para focar a linha correspondente.'}, 'light_vector': {'title': 'Vetor de luz 2D, tipo de fonte (Feixe vs. Cone) e impacto', 'short': 'Controla graficamente origem -> ponto de impacto, ângulo (°), intensidade (%) e largura/diâmetro.', 'detail': '• Arraste no painel 2D do ponto amarelo de origem até a ponta da seta:\n  - A direção define o ângulo de incidência (0°–360°, padrão 135°).\n  - O comprimento controla a intensidade especular (%).\n• Cone de luz (Cone): holofote com diâmetro ajustável (%).\n• Feixe de luz (Beam): faixa luminosa linear com largura ajustável (%).'}, 'inner_shimmer': {'title': 'Brilho interno acompanhando o contorno', 'short': 'Projeta um brilho metálico suave da borda interna da moldura para o centro da imagem.', 'detail': 'O brilho interno acompanha o contorno mais interno e pode seguir a luz principal, brilhar acima-esquerda, em contraluz (baixo-direita) ou em toda a volta.'}, 'surface_finish': {'title': 'Acabamento: Escovado, Grão, Penas, Pelo e Escamas', 'short': 'Controla o acabamento de Espelho e Cetim até Escovado, Grão, Penas, Pelo e Escamas.', 'detail': '• Espelho / Cetim: brilho polido ou acabamento acetinado suave.\n• Escovado: linhas direcionais finas com granulação e ângulo ajustáveis.\n• Grão: microtextura uniforme sem riscos direcionais.\n• Penas, Pelo e Escamas: texturas orgânicas com tamanho, comprimento, densidade e direção.\n• Direção «Segue a luz» (-1) ou ângulo fixo (0° = direita).'}, 'lighting_glow': {'title': 'Efeitos de luz, Brilho e Halo (Bloom)', 'short': 'Controla luz automática, brilho especular, halo suave (Bloom), contraste do chanfro e brilho interno.', 'detail': '• Luz automática (desde Community) ou painel 2D Cone/Feixe (Atelier).\n• Brilho e Halo (Bloom): criam uma aura suave em torno dos reflexos.\n• Contraste de chanfro e brilho interno: destacam o volume 3D.'}, 'support': {'title': 'Suporte', 'short': 'Suporte é oferecido apenas para Look, Atelier e Team.', 'detail': 'Suporte é oferecido apenas para Look, Atelier e Team.\nContato: https://www.ready-4-it.com/contact'}}
